exercises.solution:
def jumlah_komponen(rasio, ambang):
    berjalan = 0.0
    for i, r in enumerate(rasio, start=1):
        berjalan += r
        if berjalan >= ambang - 1e-9:
            return i
    return len(rasio)

def korelasi_dari_kovariansi(K):
    n = len(K)
    return [[round(K[i][j] / (K[i][i] * K[j][j]) ** 0.5, 4) + 0.0 for j in range(n)] for i in range(n)]
